-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

CREATE OR REPLACE FUNCTION public.message_after_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.conversation_id is null then
    return new;
  end if;

  update public.conversations
  set last_message_id = new.id,
      last_message_at = new.created_at,
      last_message_preview = left(case when char_length(btrim(new.body)) = 0 then 'Photo' else new.body end, 140)
  where id = new.conversation_id;

  if new.read_at is null and new.kind = 'message' then
    insert into public.conversation_unreads (conversation_id, user_id, unread_count)
    values (new.conversation_id, new.recipient_id, 1)
    on conflict (conversation_id, user_id)
    do update set unread_count = public.conversation_unreads.unread_count + 1;
  end if;

  return new;
end;
$function$;

grant execute on function public.message_after_insert() to anon;
grant execute on function public.message_after_insert() to authenticated;
grant execute on function public.message_after_insert() to public;
grant execute on function public.message_after_insert() to service_role;
